-- Generated by tools/balance/generate_gacha_care_gate.py; do not edit by hand.
-- Mystery Box and Lucky Wheel draws are refused while the pet is hungry or thirsty
-- (Hunger or Water ≤ 25 after time-based decay). Nothing is charged, throttled or drawn.
begin;

create function pawquest_private.gacha_care_threshold() returns integer
language sql immutable set search_path='' as $$ select 25 $$;

create function pawquest_private.gacha_care_block(p_actor uuid) returns text
language plpgsql security definer set search_path='' as $$
declare hunger_now integer; water_now integer; line integer:=pawquest_private.gacha_care_threshold();
begin
    if p_actor is null or p_actor is distinct from auth.uid() then
        raise exception 'Authentication required' using errcode='42501'; end if;
    -- Apply elapsed decay exactly like Pet Home does before judging the pet's needs.
    perform public.pet_state();
    select hunger,hydration into hunger_now,water_now from public.pets where user_id=p_actor;
    if not found then return null; end if;
    return case when hunger_now<=line and water_now<=line then 'hungry_thirsty'
        when hunger_now<=line then 'hungry' when water_now<=line then 'thirsty' end;
end $$;
revoke all on function pawquest_private.gacha_care_threshold(),pawquest_private.gacha_care_block(uuid)
    from public,anon,authenticated,service_role;

create or replace function public.item_case_open(p_banner_id uuid,p_request_id uuid) returns jsonb
language plpgsql volatile security definer set search_path='' set lock_timeout='5s' as $$
declare actor uuid:=auth.uid(); amount bigint; config public.item_case_versions%rowtype;
    previous public.item_case_openings%rowtype; receipt public.item_case_openings%rowtype;
    limits pawquest_private.item_case_api_settings%rowtype; throttle pawquest_private.item_case_request_limits%rowtype;
    stamp timestamptz; retry_seconds integer; need text; tier text; total_weight bigint; winning_item uuid; shard_balance bigint; problem text;
begin
    if actor is null then raise exception 'Authentication required' using errcode='42501'; end if;
    if p_banner_id is null or p_request_id is null then
        return jsonb_build_object('status','invalid_request','receipt',null); end if;
    -- Wallet first serializes this RPC with all existing economic operations.
    begin
        select coins into amount from public.wallets where user_id=actor for update;
    exception when lock_not_available then
        return jsonb_build_object('status','busy','receipt',null,'retry_after_seconds',1);
    end;
    if not found then return jsonb_build_object('status','account_unavailable','receipt',null); end if;
    select * into previous from public.item_case_openings where user_id=actor and request_id=p_request_id;
    if found then
        if not exists(select 1 from public.item_case_versions where id=previous.version_id and banner_id=p_banner_id) then
            return jsonb_build_object('status','request_conflict','receipt',null); end if;
        -- Recovery happens before throttle, balance, active banner or entropy.
        return pawquest_private.item_case_response(previous.id);
    end if;

    -- A hungry or thirsty pet must be cared for first (checked after recovery, before throttle or charge).
    need:=pawquest_private.gacha_care_block(actor);
    if need is not null then return jsonb_build_object('status','pet_needs_care','receipt',null,'need',need); end if;

    stamp:=clock_timestamp();
    select * into strict limits from pawquest_private.item_case_api_settings where singleton;
    select * into throttle from pawquest_private.item_case_request_limits where user_id=actor;
    if not found or stamp>=throttle.window_started_at+make_interval(secs=>limits.window_seconds) then
        insert into pawquest_private.item_case_request_limits(user_id,window_started_at,attempts) values(actor,stamp,1)
            on conflict(user_id) do update set window_started_at=excluded.window_started_at,attempts=1;
    elsif throttle.attempts>=limits.max_attempts then
        retry_seconds:=greatest(1,ceil(extract(epoch from throttle.window_started_at+make_interval(secs=>limits.window_seconds)-stamp))::integer);
        return jsonb_build_object('status','rate_limited','receipt',null,'retry_after_seconds',retry_seconds);
    else
        update pawquest_private.item_case_request_limits set attempts=attempts+1 where user_id=actor;
    end if;
    if exists(select 1 from public.wallet_transactions where user_id=actor and request_id=p_request_id)
        or exists(select 1 from public.shard_ledger where user_id=actor and request_id=p_request_id) then
        return jsonb_build_object('status','request_conflict','receipt',null); end if;
    select v.* into config from public.item_case_banners b join public.item_case_versions v on v.banner_id=b.id and v.version=b.current_version
        where b.id=p_banner_id and b.enabled and v.published_at is not null for share of b,v;
    if not found then return jsonb_build_object('status','banner_unavailable','receipt',null); end if;
    if amount<config.price_coins then return jsonb_build_object('status','insufficient_coins','receipt',null); end if;

    -- Do not filter owned/inactive items or reroll. Any changed catalog member
    -- invalidates this pool until an explicit new configuration is published.
    perform 1 from public.item_catalog i join public.item_case_pool p on p.item_id=i.id where p.version_id=config.id for share of i;
    if exists(select 1 from public.item_case_pool p join public.item_catalog i on i.id=p.item_id where p.version_id=config.id
        and (not i.active or i.code<>p.item_code or i.asset_id<>p.asset_id or i.category<>p.category or i.max_quantity<>p.max_quantity))
        or (select count(*)<>4 or sum(probability_bps)<>10000 from public.item_case_tiers where version_id=config.id) then
        return jsonb_build_object('status','configuration_unavailable','receipt',null); end if;
    -- Protect every mapped slot while settling; reject missing mappings without
    -- changing probabilities or choosing a different eligible item.
    perform 1 from public.accessory_slots s join public.item_case_pool p on p.item_id=s.item_id where p.version_id=config.id for share of s;
    perform 1 from public.furniture_slots s join public.item_case_pool p on p.item_id=s.item_id where p.version_id=config.id for share of s;
    if exists(select 1 from public.item_case_pool p where p.version_id=config.id and
        ((p.category='ACCESSORY' and not exists(select 1 from public.accessory_slots s where s.item_id=p.item_id))
        or (p.category='FURNITURE' and not exists(select 1 from public.furniture_slots s where s.item_id=p.item_id)))) then
        return jsonb_build_object('status','configuration_unavailable','receipt',null); end if;

    -- Inner subtransaction ensures expected settlement failures leave no
    -- partial economic changes; the normal attempt counter remains committed.
    begin
        tier:=pawquest_private.item_case_rarity_at(config.id,pawquest_private.item_case_random_below(10000));
        select sum(weight)::bigint into total_weight from public.item_case_pool where version_id=config.id and rarity=tier;
        if total_weight is null or total_weight<1 or total_weight>72057594037927936 then
            return jsonb_build_object('status','configuration_unavailable','receipt',null); end if;
        winning_item:=pawquest_private.item_case_item_at(config.id,tier,pawquest_private.item_case_random_below(total_weight));
        receipt:=pawquest_private.settle_item_case(actor,config.id,winning_item,p_request_id);
        select coalesce((select balance from public.shard_balances where user_id=actor and currency='ITEM_SHARD'),0) into shard_balance;
        insert into pawquest_private.item_case_response_snapshots(opening_id,item_name,item_shards_balance_after)
            select receipt.id,name,shard_balance from public.item_catalog where id=winning_item;
        return pawquest_private.item_case_response(receipt.id);
    exception
        when check_violation then
            get stacked diagnostics problem=MESSAGE_TEXT;
            if problem='Inventory capacity reached' then
                return jsonb_build_object('status','inventory_full','receipt',null);
            end if;
            -- Unexpected constraint failures must not be disguised as a
            -- successful/ordinary rejection, even though their effects roll back.
            raise exception 'Item Case opening failed; retry the same request ID' using errcode='P0001';
        when serialization_failure or deadlock_detected or lock_not_available then raise;
        when others then
            raise exception 'Item Case opening failed; retry the same request ID' using errcode='P0001';
    end;
exception when lock_not_available then
    return jsonb_build_object('status','busy','receipt',null,'retry_after_seconds',1);
end $$;

create or replace function public.lucky_wheel_spin(p_banner_id uuid,p_payment_method text,p_request_id uuid) returns jsonb
language plpgsql security definer set search_path='' set lock_timeout='5s' as $$
declare actor uuid:=auth.uid(); coins bigint; tickets bigint; shards bigint; v public.lucky_wheel_versions%rowtype;
 sector_reward public.lucky_wheel_sectors%rowtype; prior public.lucky_wheel_spins%rowtype; remaining text[];
 result public.lucky_wheel_spins%rowtype; food record; owned integer; winning_sector text; need text;
begin
 if actor is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_banner_id is null or p_request_id is null or p_payment_method is null or p_payment_method not in ('COINS','TICKET') then return jsonb_build_object('status','invalid_request'); end if;
 select w.coins into coins from public.wallets w where user_id=actor for update;
 if not found then return jsonb_build_object('status','account_unavailable'); end if;
 select * into prior from public.lucky_wheel_spins where user_id=actor and request_id=p_request_id;
 if found then
  if prior.payment_method<>p_payment_method or not exists(select 1 from public.lucky_wheel_versions where id=prior.version_id and banner_id=p_banner_id) then return jsonb_build_object('status','request_conflict'); end if;
  return pawquest_private.wheel_response(prior.id);
 end if;
 -- A hungry or thirsty pet must be cared for first (checked after recovery, before throttle or charge).
 need:=pawquest_private.gacha_care_block(actor);
 if need is not null then return jsonb_build_object('status','pet_needs_care','need',need); end if;
 if pawquest_private.wheel_request_used(actor,p_request_id) then return jsonb_build_object('status','request_conflict'); end if;
 if not pawquest_private.wheel_allow_request(actor) then return jsonb_build_object('status','rate_limited'); end if;
 select c.* into v from public.lucky_wheel_banners b join public.lucky_wheel_versions c on c.banner_id=b.id and c.version=b.current_version
 where b.id=p_banner_id and b.enabled and c.published_at is not null for share of b,c;
 if not found then return jsonb_build_object('status','banner_unavailable'); end if;
 select coalesce((select balance from public.lucky_wheel_ticket_balances where user_id=actor),0) into tickets;
 select coalesce((select balance from public.shard_balances where user_id=actor and currency='PET_SHARD'),0) into shards;
 if p_payment_method='COINS' and coins<v.price_coins then return jsonb_build_object('status','insufficient_coins'); end if;
 if p_payment_method='TICKET' and tickets<1 then return jsonb_build_object('status','insufficient_tickets'); end if;
 -- Validate every possible destination BEFORE drawing. A capacity failure cannot create a free outcome reroll.
 select i.*,r.amount into food from public.lucky_wheel_sectors r join public.item_catalog i on i.id=r.food_item_id where r.version_id=v.id and r.sector_id='FOOD' for share of i;
 if not found or not food.active or food.category<>'FOOD' then return jsonb_build_object('status','configuration_unavailable'); end if;
 perform 1 from public.pet_species s join public.pet_shard_prices q on q.species_code=s.code where q.version_id=v.id for share of s;
 if exists(select 1 from public.pet_shard_prices q join public.pet_species s on s.code=q.species_code where q.version_id=v.id and not s.published) then return jsonb_build_object('status','configuration_unavailable'); end if;
 select quantity into owned from public.user_inventory where user_id=actor and item_id=food.id for update;
 if coalesce(owned,0)::bigint+food.amount>food.max_quantity then return jsonb_build_object('status','inventory_full'); end if;
 winning_sector:=pawquest_private.wheel_sector_at(v.id,pawquest_private.item_case_random_below(10000));
 select * into strict sector_reward from public.lucky_wheel_sectors where version_id=v.id and sector_id=winning_sector;
 result.id:=gen_random_uuid(); result.user_id:=actor; result.request_id:=p_request_id; result.version_id:=v.id; result.sector_id:=sector_reward.sector_id; result.payment_method:=p_payment_method;
 result.coins_spent:=case p_payment_method when 'COINS' then v.price_coins else 0 end;
 result.tickets_spent:=case p_payment_method when 'TICKET' then 1 else 0 end;
 result.coins_earned:=0; result.pet_shards_earned:=0; result.tickets_earned:=0; result.food_quantity:=0;
 case sector_reward.sector_id
 when 'FOOD' then result.actual_reward_type:='FOOD'; result.food_item_id:=sector_reward.food_item_id; result.food_quantity:=sector_reward.amount;
 when 'COINS_50' then result.actual_reward_type:='COINS'; result.coins_earned:=sector_reward.amount;
 when 'LUCKY_TICKET_1' then result.actual_reward_type:='TICKET'; result.tickets_earned:=sector_reward.amount;
 when 'PET_UNLOCK' then
  select array_agg(q.species_code order by q.species_code) into remaining from public.pet_shard_prices q where q.version_id=v.id
  and not exists(select 1 from public.user_pet_unlocks u where u.user_id=actor and u.species_code=q.species_code);
  if coalesce(cardinality(remaining),0)=0 then result.actual_reward_type:='PET_UNLOCK_CONVERTED_TO_SHARDS'; result.pet_shards_earned:=v.fallback_pet_shards;
  else result.actual_reward_type:='PET_UNLOCKED'; result.selected_pet_id:=remaining[1+pawquest_private.item_case_random_below(cardinality(remaining))::integer]; end if;
 else result.actual_reward_type:='PET_SHARDS'; result.pet_shards_earned:=sector_reward.amount;
 end case;
 result.coins_balance_after:=coins-result.coins_spent+result.coins_earned;
 result.pet_shards_balance_after:=shards+result.pet_shards_earned;
 result.tickets_balance_after:=tickets-result.tickets_spent+result.tickets_earned; result.created_at:=clock_timestamp();
 insert into pawquest_private.wheel_requests values(actor,p_request_id,'WHEEL');
 insert into public.lucky_wheel_spins select result.*;
 if result.coins_spent>0 then insert into public.wallet_transactions(user_id,kind,request_id,lucky_wheel_spin_id,wheel_leg)
 values(actor,'lucky_wheel',gen_random_uuid(),result.id,'PAYMENT'); end if;
 if result.coins_earned>0 then insert into public.wallet_transactions(user_id,kind,request_id,lucky_wheel_spin_id,wheel_leg)
 values(actor,'lucky_wheel',gen_random_uuid(),result.id,'REWARD'); end if;
 if result.tickets_spent>0 then insert into public.lucky_wheel_ticket_ledger(user_id,spin_id,leg,delta,balance_after) values(actor,result.id,'PAYMENT',-1,0); end if;
 if result.tickets_earned>0 then insert into public.lucky_wheel_ticket_ledger(user_id,spin_id,leg,delta,balance_after) values(actor,result.id,'REWARD',1,0); end if;
 if result.pet_shards_earned>0 then insert into public.shard_ledger(user_id,currency,request_id,reason,delta,balance_after,lucky_wheel_spin_id)
 values(actor,'PET_SHARD',p_request_id,'WHEEL_REWARD',result.pet_shards_earned,0,result.id); end if;
 if result.food_quantity>0 then perform pawquest_private.adjust_inventory(actor,result.food_item_id,result.food_quantity); end if;
 if result.selected_pet_id is not null then insert into public.user_pet_unlocks(user_id,species_code,source,source_id) values(actor,result.selected_pet_id,'WHEEL',result.id); end if;
 return pawquest_private.wheel_response(result.id);
exception when lock_not_available then return jsonb_build_object('status','busy');
end $$;

comment on function pawquest_private.gacha_care_block(uuid) is
    'Returns hungry/thirsty/hungry_thirsty when Mystery Box and Lucky Wheel draws must wait for pet care, else null.';
commit;
